import { useCallback, useEffect, useRef, useState } from "react";
import { ArrowRight, ChevronLeft, Pause, Play } from "lucide-react";
import spanLogo from "../assets/span-logo.svg";
import { LOOKUP_TABLE } from "../data/mozart";
import { useDialogFocus } from "../lib/dialogFocus";
import { Button } from "./Button";

const cutoutAtlas =
  "data:image/jpeg;base64,";
const chapters = [
  {
    eyebrow: "A little something from Span",
    title: "Hey, Bob.",
    copy: "We saw you studied music. So we made you something to play with. Have you come across Mozart’s musical dice game?",
    cta: "Show me",
    duration: 8500,
  },
  {
    eyebrow: "A curious invention · 1793",
    title: "A little chance.\nA lot of thought.",
    copy: "Published under Mozart’s name, the game offered a remarkable shortcut: a whole minuet, assembled from 176 carefully chosen measures.",
    cta: "How does it work?",
    duration: 9000,
  },
  {
    eyebrow: "Sixteen choices, one composition",
    title: "The choices change.\nThe music fits.",
    copy: "Two dice pick a measure from each column of the table. Sixteen rolls later, you have a minuet. The structure makes room for chance.",
    cta: "And the connection?",
    duration: 9500,
  },
  {
    eyebrow: "From a musical idea to an engineering one",
    title: "Less arranging.\nMore creating.",
    copy: "Good systems give time back. Src, Span’s AI engineering intelligence, brings that idea to reports and codebase questions—leaving room for the work that matters.",
    cta: "Now, the fun part",
    duration: 11000,
  },
  {
    eyebrow: "Your invitation",
    title: "Now you try, Bob.",
    copy: "Roll a minuet. Choose the instruments. Find a combination that sounds like you.",
    cta: "Let’s roll",
    duration: 0,
  },
];
function TableIllustration() {
  return (
    <div className="story-table-art">
      <div className="table-paper">
        <div className="table-paper-title">
          <span>Musikalisches Würfelspiel</span>
          <b>176</b>
        </div>
        <div className="story-matrix">
          {LOOKUP_TABLE.flat().map((id, i) => (
            <span
              key={i}
              className={
                Math.floor(i / 16) === [5, 3, 7, 2, 6, 4, 5, 8, 3, 6, 4, 7, 5, 2, 9, 5][i % 16] ? "chosen" : ""
              }
            >
              {id}
            </span>
          ))}
        </div>
      </div>
      <div className="table-music-ribbon">
        <span>Minuetto</span>
        <svg viewBox="0 0 450 58">
          {[18, 24, 30, 36, 42].map((y) => (
            <path key={y} d={`M4 ${y}h442`} stroke="currentColor" strokeWidth=".6" />
          ))}
          {Array.from({ length: 16 }, (_, i) => (
            <g key={i} style={{ "--note": i } as React.CSSProperties}>
              <ellipse cx={14 + i * 28} cy={24 + (i % 3) * 6} rx="4" ry="3" fill="currentColor" />
              <path d={`M${18 + i * 28} ${24 + (i % 3) * 6}v-18`} stroke="currentColor" />
            </g>
          ))}
        </svg>
      </div>
      <span className="handwritten-note">a place for every possibility</span>
    </div>
  );
}
export function Theater({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [chapter, setChapter] = useState(0);
  const [leaving, setLeaving] = useState(false);
  const [closing, setClosing] = useState(false);
  const [paused, setPaused] = useState(false);
  const [reduced, setReduced] = useState(false);
  const ref = useRef<HTMLElement>(null);
  const transition = useRef<number | undefined>(undefined);
  const close = useCallback(() => {
    window.clearTimeout(transition.current);
    setClosing(true);
    transition.current = window.setTimeout(onClose, reduced ? 0 : 700);
  }, [onClose, reduced]);
  useDialogFocus(open, ref, close);
  useEffect(() => {
    if (!open) return;
    setChapter(0);
    setLeaving(false);
    setClosing(false);
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    setReduced(reduce);
    setPaused(reduce);
    return () => window.clearTimeout(transition.current);
  }, [open]);
  const go = useCallback(
    (next: number) => {
      if (leaving || closing) return;
      if (next >= chapters.length) {
        close();
        return;
      }
      if (reduced) {
        setChapter(next);
        return;
      }
      setLeaving(true);
      transition.current = window.setTimeout(() => {
        setChapter(next);
        setLeaving(false);
      }, 460);
    },
    [close, leaving, closing, reduced],
  );
  useEffect(() => {
    if (!open || paused || leaving || closing) return;
    const duration = chapters[chapter]!.duration;
    if (!duration) return;
    const timer = window.setTimeout(() => go(chapter + 1), duration);
    return () => window.clearTimeout(timer);
  }, [open, paused, leaving, closing, chapter, go]);
  if (!open) return null;
  const scene = chapters[chapter]!;
  return (
    <section
      className={`paper-story ${closing ? "story-closing" : ""}`}
      role="dialog"
      aria-modal="true"
      aria-label="A little chance music for Bob"
      ref={ref}
    >
      <header className="paper-story-header">
        <img className="span-logo" src={spanLogo} alt="Span" />
        <span>For Bob Pisani</span>
        <Button autoFocus variant="ghost" onClick={close}>
          Skip story
          <ArrowRight />
        </Button>
      </header>
      <div className={`paper-story-scene story-scene-${chapter} ${leaving ? "turning-scene" : ""}`}>
        <div className="paper-story-copy" key={`copy-${chapter}`}>
          <p className="kicker">{scene.eyebrow}</p>
          <h1>
            {scene.title.split("\n").map((line, i) => (
              <span key={i}>{line}</span>
            ))}
          </h1>
          <p className="story-prose">{scene.copy}</p>
          <Button className="story-continue" disabled={leaving || closing} onClick={() => go(chapter + 1)}>
            {scene.cta}
            <ArrowRight />
          </Button>
          {chapter === 0 && <span className="signed-note">Made for you, by Span.</span>}
        </div>
        <div className="paper-story-art" key={`art-${chapter}`} aria-hidden="true">
          {chapter === 2 ? (
            <TableIllustration />
          ) : (
            <>
              <div
                className={`cutout-illustration cutout-${chapter}`}
                style={{ backgroundImage: `url(${cutoutAtlas})` }}
              />
              {chapter === 1 && <span className="date-impression">1793</span>}
              {chapter === 3 && (
                <span className="art-marginalia">
                  a little more time
                  <br />
                  for what matters.
                </span>
              )}
            </>
          )}
        </div>
      </div>
      <div className="paper-story-bottom">
        <div className="story-chapters">
          <Button
            variant="ghost"
            disabled={chapter === 0 || leaving || closing}
            onClick={() => go(chapter - 1)}
            aria-label="Previous scene"
          >
            <ChevronLeft />
          </Button>
          <span className="story-counter">
            0{chapter + 1}
            <i>/ 05</i>
          </span>
          <div className="chapter-progress" aria-label={`Scene ${chapter + 1} of 5`}>
            {chapters.map((_, i) => (
              <button
                key={i}
                aria-label={`Go to scene ${i + 1}`}
                aria-current={chapter === i ? "step" : undefined}
                disabled={leaving || closing}
                onClick={() => go(i)}
                className={i <= chapter ? "reached" : ""}
              />
            ))}
          </div>
          <Button
            variant="ghost"
            onClick={() => setPaused((v) => !v)}
            aria-label={paused ? "Play story" : "Pause story"}
          >
            {paused ? <Play /> : <Pause />}
          </Button>
        </div>
        <span className="story-footer-note">A little chance music</span>
      </div>
    </section>
  );
}
